using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class TicketPredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Confidence { get; set; } = new();
}

public class ModelMetrics
{
    public float MacroAccuracy { get; set; }
    public float MicroAccuracy { get; set; }
    public float LogLoss { get; set; }
    public float LogLossReduction { get; set; }
    public PerClassMetric[] PerClassMetrics { get; set; } = [];
}

public class PerClassMetric
{
    public string Class { get; set; } = string.Empty;
    public double Precision { get; set; }
    public double Recall { get; set; }
    public double F1Score { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly ModelMetrics _metrics;
    private readonly string[] _classLabels;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 0);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.3);

        var pipeline = _mlContext.Transforms.Text
                .FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        // Extract class labels from the trained model's key-to-value mapping
        var schema = _model.GetOutputSchema(split.TrainSet.Schema);
        var labelColumn = schema.GetColumnOrNull("Label");
        if (labelColumn.HasValue)
        {
            var keyType = labelColumn.Value.Type as Microsoft.ML.Data.KeyDataViewType;
            var labelMetadata = labelColumn.Value.Annotations;
            var buffer = default(VBuffer<ReadOnlyMemory<char>>);
            labelMetadata.GetValue("KeyValues", ref buffer);
            _classLabels = buffer.DenseValues().Select(v => v.ToString()).ToArray();
        }
        else
        {
            _classLabels = ["Billing", "General", "Technical"];
        }

        var predictions = _model.Transform(split.TestSet);
        var eval = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        _metrics = new ModelMetrics
        {
            MacroAccuracy = (float)eval.MacroAccuracy,
            MicroAccuracy = (float)eval.MicroAccuracy,
            LogLoss = (float)eval.LogLoss,
            LogLossReduction = (float)eval.LogLossReduction,
            PerClassMetrics = eval.PerClassPrecision
                .Select((p, i) => new PerClassMetric
                {
                    Class = i < _classLabels.Length ? _classLabels[i] : $"Class{i}",
                    Precision = eval.PerClassPrecision[i],
                    Recall = eval.PerClassRecall[i],
                    F1Score = 2 * (eval.PerClassPrecision[i] * eval.PerClassRecall[i])
                             / (eval.PerClassPrecision[i] + eval.PerClassRecall[i] is 0
                                 ? 1
                                 : eval.PerClassPrecision[i] + eval.PerClassRecall[i])
                }).ToArray()
        };

        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model);
    }

    public TicketPredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < prediction.Score.Length && i < _classLabels.Length; i++)
        {
            confidence[_classLabels[i]] = prediction.Score[i];
        }

        return new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public ModelMetrics GetMetrics() => _metrics;
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly TicketClassifierService _classifierService;

    public TicketController(TicketClassifierService classifierService)
    {
        _classifierService = classifierService;
    }

    [HttpPost("classify")]
    public ActionResult<TicketPredictionResponse> Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(_classifierService.Predict(request));
    }

    [HttpGet("metrics")]
    public ActionResult<ModelMetrics> GetMetrics()
    {
        return Ok(_classifierService.GetMetrics());
    }
}

